package dev.rodrigosambade.oca;
import dev.rodrigosambade.net.ConnectivityAndInternetAccess;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Duration;
public final class GameClient{public static void main(String[]a)throws Exception{if(a.length<3)throw new IllegalArgumentException("host port nick");String host=a[0];int port=Integer.parseInt(a[1]);ConnectivityAndInternetAccess.requireInternetForRemoteHost(host,Duration.ofSeconds(2));try(Socket s=new Socket()){s.connect(new InetSocketAddress(host,port),3000);try(var in=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));var out=new BufferedWriter(new OutputStreamWriter(s.getOutputStream(),StandardCharsets.UTF_8));var console=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8))){out.write(a[2]);out.newLine();out.flush();for(String line;(line=in.readLine())!=null;){System.out.println(line);if(line.equals("TURN")){System.out.print("ENTER para tirar…");console.readLine();out.write("ROLL");out.newLine();out.flush();}if(line.startsWith("WIN|"))break;}}}}}
